function now() {
  return new Date().toISOString();
}

function next(state, index) {
  state.index = index;
  if (index >= TESTS.length) {
    const results = global.get("ft_results") || [];
    const failed = results.filter((r) => !r.ok);
    state.running = false;
    state.finishedAt = now();
    state.passed = results.length - failed.length;
    state.failed = failed.length;
    global.set("ft_active", null);
    global.set("ft_state", state);
    node.status({
      fill: failed.length ? "red" : "green",
      shape: "dot",
      text: state.passed + " passed, " + state.failed + " failed",
    });
    return [null, { payload: { state, results } }];
  }
  const t = TESTS[index];
  state.testStartedAt = Date.now();
  global.set("ft_state", state);
  global.set("ft_active", t.id);
  node.status({ fill: "blue", shape: "dot", text: "running " + t.id + " (" + (index + 1) + "/" + TESTS.length + ")" });
  return [{ target: "FT " + t.id, ftTest: t }, null];
}

if (msg.ftStart) {
  global.set("ft_results", []);
  global.set("ft_run", Date.now().toString(36));
  const state = {
    running: true,
    runId: global.get("ft_run"),
    startedAt: now(),
    finishedAt: null,
    total: TESTS.length,
    index: -1,
  };
  node.log("[FT] starting " + TESTS.length + " tests");
  return next(state, 0);
}

const state = global.get("ft_state");
if (!state || !state.running) return null;
const cur = TESTS[state.index];

let result;
if (msg.ft && msg.ft.id === cur.id) {
  result = { id: cur.id, ok: !!msg.ft.ok, detail: msg.ft.detail || "" };
} else if (msg.error) {
  // link call timeout or a missing target
  const reason = msg.error.message || String(msg.error);
  result = {
    id: cur.id,
    ok: false,
    detail: reason === "timeout" ? "no result within 30 s" : "no result: " + reason,
  };
} else {
  return null;
}
result.name = cur.name;
result.tab = cur.tab;
result.durationMs = Date.now() - state.testStartedAt;

const results = global.get("ft_results") || [];
results.push(result);
global.set("ft_results", results);
node.log("[FT] " + (result.ok ? "PASS" : "FAIL") + " " + result.id + " " + result.name + (result.detail ? " - " + result.detail : ""));
return next(state, state.index + 1);

// Generated by test/functional/build-flow.js
const { state, results } = msg.payload;
const failed = results.filter((r) => !r.ok);
const lines = results.map((r) => (r.ok ? "PASS " : "FAIL ") + r.id + " " + r.name + (r.ok ? "" : " - " + r.detail));
const summary = "[FT] finished: " + state.passed + " passed, " + state.failed + " failed, " + state.total + " total";
node.log(summary);
failed.forEach((r) => node.warn("[FT] FAIL " + r.id + " " + r.name + " - " + r.detail));
node.warn(summary);
msg.payload = { summary, passed: state.passed, failed: state.failed, total: state.total, lines };
return msg;

msg.payload = {
  state: global.get("ft_state") || null,
  results: global.get("ft_results") || [],
};
return msg;
